//! PG80 no-account/no-network background lifecycle. This is a fixture scope,
//! not the general download providers or Steam-account processing.
use std::{sync::{Arc,Mutex,atomic::{AtomicBool,AtomicU64,Ordering},mpsc::{self,Sender}},thread::{self,JoinHandle},time::{Duration,Instant}};
use serde_json::Value;
use super::pg79_authority::Authority;
type Load = dyn Fn()->Result<Value,String> + Send + Sync;
struct Running{stop:Sender<()>,worker:JoinHandle<Result<(),String>>,watcher_alive:Arc<AtomicBool>}
#[derive(Default)]struct Slot{running:Option<Running>,terminal:Option<String>,unconfirmed:bool}
fn reap_finished(slot:&mut Slot)->Result<(),String>{if let Some(error)=&slot.terminal{return Err(error.clone())}if slot.running.as_ref().is_some_and(|r|r.worker.is_finished()){let run=slot.running.take().unwrap();let outcome=match run.worker.join(){Ok(v)=>v,Err(_)=>Err("background worker panicked; database outcome unconfirmed".into())};if let Err(e)=outcome{slot.terminal=Some(e.clone());return Err(e)}}Ok(())}
fn existing_ready(slot:&mut Slot)->Result<bool,String>{if slot.unconfirmed{return Err("watcher start unconfirmed; stop and join required".into())}reap_finished(slot)?;if let Some(run)=&slot.running{if !run.watcher_alive.load(Ordering::Acquire){return Err("process watcher not confirmed alive".into())}return Ok(true)}Ok(false)}
fn wait_ready(slot:&mut Slot,ready:mpsc::Receiver<Result<(),String>>,deadline:Instant)->Result<(),String>{if Instant::now()>=deadline{slot.unconfirmed=true;return Err("watcher start deadline expired; worker retained".into())}let result=ready.recv_timeout(deadline.saturating_duration_since(Instant::now()));if Instant::now()>=deadline{slot.unconfirmed=true;return Err("watcher start deadline expired; worker retained".into())}match result{Ok(Ok(()))=>{if slot.running.as_ref().is_some_and(|run|run.watcher_alive.load(Ordering::Acquire)){Ok(())}else{slot.unconfirmed=true;Err("watcher exited during start; worker retained".into())}},Ok(Err(e))=>{slot.unconfirmed=true;Err(e)},Err(_)=>{slot.unconfirmed=true;Err("watcher start unconfirmed; worker retained".into())}}}
pub struct OwnedBackground{slot:Mutex<Slot>,samples:Arc<AtomicU64>}
fn validate(settings:&Value)->Result<(),String>{let download=settings.get("download").ok_or("missing download settings")?;for provider in ["Valve","Faceit","Renown","5EPlay"] {for suffix in ["AtStartup","InBackground"]{let key=format!("download{provider}Demos{suffix}");if download.get(&key).and_then(Value::as_bool)!=Some(false){return Err(format!("owned fixture requires disabled {key}"))}}}if settings.get("steamApiKey").and_then(Value::as_str)!=Some(""){return Err("owned fixture requires empty Steam API key".into())}if std::env::var_os("STEAM_API_KEYS").as_deref()!=Some(std::ffi::OsStr::new("")){return Err("owned fixture requires explicit empty Steam API fallback".into())}Ok(())}
fn history(auth:&Authority)->Result<u64,String>{let mut c=auth.connect()?;c.execute("DELETE FROM download_history WHERE downloaded_at < now() - interval '1 month'",&[]).map_err(|e|format!("owned history cleanup: {e}"))}
fn steam(auth:&Authority)->Result<(),String>{let mut c=auth.connect()?;let check=(||->Result<(),String>{let row=c.query_opt("SELECT (extract(epoch from date)*1000)::float8 FROM timestamps WHERE name='SyncWithSteam'",&[]).map_err(|e|e.to_string())?;let expired=row.map(|r|chrono::Utc::now().timestamp_millis() as f64-r.get::<_,f64>(0)>=86_400_000.0).unwrap_or(true);if expired{let row=c.query_one("SELECT EXISTS(SELECT 1 FROM players p WHERE NOT EXISTS(SELECT 1 FROM steam_accounts s WHERE s.steam_id=p.steam_id)), EXISTS(SELECT 1 FROM steam_accounts)",&[]).map_err(|e|e.to_string())?;if row.get::<_,bool>(0)||row.get::<_,bool>(1){return Err("nonempty Steam synchronization is unsupported in owned fixture".into())}}Ok(())})();let stamp=c.execute("INSERT INTO timestamps(name,date) VALUES('SyncWithSteam',now()) ON CONFLICT(name) DO UPDATE SET date=excluded.date",&[]).map_err(|e|format!("owned Steam timestamp: {e}"));match(check,stamp){(Ok(()),Ok(_))=>Ok(()),(Err(a),Ok(_))=>Err(a),(Ok(()),Err(b))=>Err(b),(Err(a),Err(b))=>Err(format!("{a}; {b}"))}}
fn released(rx:mpsc::Receiver<()>)->bool{rx.recv().is_ok()}
fn worker_loop(rx:mpsc::Receiver<()>,validate:impl Fn()->Result<(),String>,history:impl Fn()->Result<(),String>,steam:impl Fn()->Result<(),String>,watcher:impl Fn()->Result<(),String>,poll:Duration,hour:Duration)->Result<(),String>{watcher()?;validate()?;history()?;watcher()?;validate()?;steam()?;watcher()?;let mut next=Instant::now()+hour;loop{match rx.recv_timeout(poll){Ok(())|Err(mpsc::RecvTimeoutError::Disconnected)=>return Ok(()),Err(mpsc::RecvTimeoutError::Timeout)=>{watcher()?;validate()?;if Instant::now()>=next{steam()?;next=Instant::now()+hour}}}}}
impl OwnedBackground{
 pub fn new()->Self{Self{slot:Mutex::new(Slot::default()),samples:Arc::new(AtomicU64::new(0))}}
 #[cfg(feature="pg80-owned-observe")] pub fn observe(&self,timeout:Duration)->Result<Value,String>{let deadline=Instant::now()+timeout;let slot=loop{if Instant::now()>=deadline{return Err("background observation unconfirmed".into())}match self.slot.try_lock(){Ok(g)=>break g,Err(std::sync::TryLockError::Poisoned(_))=>return Err("background observation poisoned".into()),Err(std::sync::TryLockError::WouldBlock)=>thread::sleep(Duration::from_millis(5))}};Ok(serde_json::json!({"running":slot.running.is_some(),"watcherAlive":slot.running.as_ref().is_some_and(|r|r.watcher_alive.load(Ordering::Acquire)),"unconfirmed":slot.unconfirmed,"terminal":slot.terminal,"periodicSamples":self.samples.load(Ordering::Acquire)}))}

 /// Start exactly one tracked worker. Initial history and Steam work is asynchronous.
 pub fn start(&self,auth:Arc<Authority>,load:Arc<Load>,timeout:Duration)->Result<(),String>{let deadline=Instant::now()+timeout;let mut slot=loop{if Instant::now()>=deadline{return Err("background start unconfirmed".into())}match self.slot.try_lock(){Ok(g)=>break g,Err(std::sync::TryLockError::Poisoned(_))=>return Err("background owner poisoned".into()),Err(std::sync::TryLockError::WouldBlock)=>thread::sleep(Duration::from_millis(5))}};if existing_ready(&mut slot)?{return Ok(())}validate(&load()?)?;if Instant::now()>=deadline{return Err("background start deadline expired".into())}let(tx,rx)=mpsc::channel();let(ready_tx,ready_rx)=mpsc::sync_channel::<Result<(),String>>(1);let(release_tx,release_rx)=mpsc::sync_channel::<()>(1);self.samples.store(0,Ordering::Release);let samples=self.samples.clone();let watcher_alive=Arc::new(AtomicBool::new(false));let alive_for_worker=watcher_alive.clone();let worker=thread::Builder::new().name("pg80-owned-background".into()).spawn(move||{let(wtx,wrx)=mpsc::channel();let watch_load=load.clone();let alive=alive_for_worker.clone();alive.store(true,Ordering::Release);let watcher=match thread::Builder::new().name("pg80-process-watcher".into()).spawn(move||{let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||super::pg80_watcher::run(wrx,&*watch_load,ready_tx,samples))).unwrap_or_else(|_|Err("process watcher panicked; outcome unconfirmed".into()));alive.store(false,Ordering::Release);result}){Ok(w)=>w,Err(e)=>{alive_for_worker.store(false,Ordering::Release);return Err(format!("watcher spawn: {e}"))}};if !released(release_rx){let _=wtx.send(());let joined=watcher.join().unwrap_or_else(|_|Err("watcher join failed; outcome unconfirmed".into()));return Err(format!("background not released after watcher startup failure; watcher: {joined:?}"))}let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||worker_loop(rx,||validate(&load()?),||history(&auth).map(|_|()),||steam(&auth),||if watcher.is_finished(){Err("process watcher stopped unexpectedly".into())}else{Ok(())},Duration::from_secs(30),Duration::from_secs(3600)))).unwrap_or_else(|_|Err("background worker panicked; outcome unconfirmed".into()));let _=wtx.send(());let watched=watcher.join().unwrap_or_else(|_|Err("process watcher panicked; outcome unconfirmed".into()));match(result,watched){(Ok(()),Ok(()))=>Ok(()),(Err(a),Ok(()))=>Err(a),(Ok(()),Err(b))=>Err(b),(Err(a),Err(b))=>Err(format!("{a}; watcher: {b}"))}}).map_err(|e|format!("background worker spawn: {e}"))?;slot.running=Some(Running{stop:tx,worker,watcher_alive});wait_ready(&mut slot,ready_rx,deadline)?;if Instant::now()>=deadline{slot.unconfirmed=true;return Err("watcher start deadline expired; worker retained".into())}if release_tx.send(()).is_err(){slot.unconfirmed=true;return Err("background start release unconfirmed; worker retained".into())}Ok(())}
 /// Stop timer and retain any still-running writer on timeout; retry remains possible.
 pub fn stop(&self,timeout:Duration)->Result<(),String>{let deadline=Instant::now()+timeout;let mut slot=loop{if Instant::now()>=deadline{return Err("background stop unconfirmed".into())}match self.slot.try_lock(){Ok(g)=>break g,Err(std::sync::TryLockError::Poisoned(_))=>return Err("background owner poisoned; outcome unconfirmed".into()),Err(std::sync::TryLockError::WouldBlock)=>thread::sleep(Duration::from_millis(5))}};if let Some(error)=&slot.terminal{return Err(error.clone())}let Some(run)=slot.running.as_ref()else{return Ok(())};let _=run.stop.send(());while !run.worker.is_finished(){if Instant::now()>=deadline{return Err("background writer shutdown unconfirmed".into())}thread::sleep(Duration::from_millis(5))}let run=slot.running.take().unwrap();match run.worker.join(){Ok(Ok(()))=>{slot.unconfirmed=false;Ok(())},Ok(Err(e))=>{slot.terminal=Some(e.clone());Err(e)},Err(_)=>{let e="background worker panicked; database outcome unconfirmed".to_string();slot.terminal=Some(e.clone());Err(e)}}}
}
#[cfg(test)]mod tests{use super::*;use serde_json::json;
 #[test]fn source_original_startup_work_order_and_stop(){let oracle:Value=serde_json::from_str(include_str!("../tests/fixtures/pg80-original-background-oracle.json")).unwrap();let expected:Vec<String>=oracle["trace"].as_array().unwrap().iter().filter_map(|v|v.as_str()).filter(|s|*s=="download-last"||*s=="steam-check").map(str::to_owned).collect();let events=Mutex::new(Vec::<String>::new());let(tx,rx)=mpsc::channel();tx.send(()).unwrap();worker_loop(rx,||Ok(()),||{events.lock().unwrap().push("download-last".into());Ok(())},||{events.lock().unwrap().push("steam-check".into());Ok(())},||Ok(()),Duration::from_millis(10),Duration::from_secs(3600)).unwrap();assert_eq!(*events.lock().unwrap(),expected);assert!(oracle["trace"].as_array().unwrap().contains(&json!("interval:3600000")));}
 #[test]fn failed_readiness_never_releases_background_work(){use std::sync::atomic::AtomicUsize;let count=Arc::new(AtomicUsize::new(0));let observed=count.clone();let(tx,rx)=mpsc::sync_channel(1);let job=thread::spawn(move||{if released(rx){observed.fetch_add(1,Ordering::SeqCst);}});drop(tx);job.join().unwrap();assert_eq!(count.load(Ordering::SeqCst),0);let(tx,rx)=mpsc::sync_channel(1);let observed=count.clone();let job=thread::spawn(move||{if released(rx){observed.fetch_add(1,Ordering::SeqCst);}});tx.send(()).unwrap();job.join().unwrap();assert_eq!(count.load(Ordering::SeqCst),1);}
 #[test]fn unconfirmed_watcher_start_cannot_be_reused_until_joined(){let(tx,rx)=mpsc::channel();let worker=thread::spawn(move||{let _=rx.recv();Ok(())});let(ready_tx,ready_rx)=mpsc::sync_channel(1);let mut slot=Slot{running:Some(Running{stop:tx,worker,watcher_alive:Arc::new(AtomicBool::new(true))}),terminal:None,unconfirmed:false};assert!(wait_ready(&mut slot,ready_rx,Instant::now()+Duration::from_millis(30)).unwrap_err().contains("worker retained"));assert!(existing_ready(&mut slot).unwrap_err().contains("unconfirmed"));drop(ready_tx);let owner=OwnedBackground{slot:Mutex::new(slot),samples:Arc::new(AtomicU64::new(0))};owner.stop(Duration::from_secs(1)).unwrap();assert!(!owner.slot.lock().unwrap().unconfirmed);}
 #[test]fn dead_watcher_cannot_be_reused_while_worker_still_runs(){let(tx,rx)=mpsc::channel();let worker=thread::spawn(move||{let _=rx.recv();Ok(())});let mut slot=Slot{running:Some(Running{stop:tx,worker,watcher_alive:Arc::new(AtomicBool::new(false))}),terminal:None,unconfirmed:false};assert!(existing_ready(&mut slot).unwrap_err().contains("watcher not confirmed"));let owner=OwnedBackground{slot:Mutex::new(slot),samples:Arc::new(AtomicU64::new(0))};owner.stop(Duration::from_secs(1)).unwrap();}
 #[test]fn completed_failed_worker_cannot_be_reported_running(){let(tx,_rx)=mpsc::channel();let worker=thread::spawn(||Err("owned DB failure".to_string()));while !worker.is_finished(){thread::yield_now()}let mut slot=Slot{running:Some(Running{stop:tx,worker,watcher_alive:Arc::new(AtomicBool::new(false))}),terminal:None,unconfirmed:false};assert_eq!(reap_finished(&mut slot).unwrap_err(),"owned DB failure");assert!(slot.running.is_none());assert_eq!(reap_finished(&mut slot).unwrap_err(),"owned DB failure");}
 #[test]fn rejects_enabled_provider_and_nonempty_key_before_work(){let s=json!({"download":{"downloadValveDemosAtStartup":true},"steamApiKey":""});assert!(validate(&s).unwrap_err().contains("disabled"));let s=json!({"download":{},"steamApiKey":"secret"});assert!(validate(&s).is_err());}
}


